/* ============================================================
   App.css — DebugFlow dark developer-tool theme
   ============================================================ */

/* ── CSS Variables ─────────────────────────────────────────── */
:root {
  --bg:          #0d1117;
  --bg-panel:    #161b22;
  --bg-surface:  #1c2128;
  --bg-code:     #0d1117;
  --border:      #30363d;
  --border-focus:#58a6ff;
  --text:        #c9d1d9;
  --text-muted:  #6e7681;
  --text-heading:#e6edf3;
  --accent:      #58a6ff;
  --accent-dark: #1f6feb;
  --green:       #3fb950;
  --green-bg:    #0d4429;
  --red:         #f85149;
  --red-bg:      #3b0a0a;
  --yellow:      #d29922;
  --yellow-bg:   #3d2d00;
  --diff-add-bg: #0d4429;
  --diff-del-bg: #3b0a0a;
  --diff-hunk:   #1f6feb;

  --font-sans:   -apple-system, "Segoe UI", system-ui, sans-serif;
  --font-mono:   "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

  --radius:      6px;
  --radius-lg:   10px;
  --shadow:      0 1px 3px rgba(0,0,0,.4);
}

/* ── Reset / Base ───────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 15px;
  -webkit-text-size-adjust: 100%;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  line-height: 1.6;
  min-height: 100vh;
}

/* Visually hidden helper for screen-reader labels */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Header ─────────────────────────────────────────────────── */
.app-header {
  background: var(--bg-panel);
  border-bottom: 1px solid var(--border);
  padding: 0.9rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 10;
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.header-logo {
  font-size: 1.6rem;
  color: var(--accent);
}

.header-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-heading);
  letter-spacing: -0.01em;
}

.header-tagline {
  font-size: 0.78rem;
  color: var(--text-muted);
}

/* Backend status pill */
.backend-status {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.78rem;
  padding: 0.3rem 0.7rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg-surface);
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.backend-status--online  .status-dot { background: var(--green); }
.backend-status--offline .status-dot { background: var(--red); }
.backend-status--checking .status-dot { background: var(--yellow); }
.backend-status--online  { color: var(--green); border-color: var(--green-bg); }
.backend-status--offline { color: var(--red);   border-color: var(--red-bg); }

/* ── Main layout ────────────────────────────────────────────── */
.app-main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1.5rem 1.5rem 3rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.input-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
}

@media (max-width: 860px) {
  .input-row {
    grid-template-columns: 1fr;
  }
}

/* ── Panels ─────────────────────────────────────────────────── */
.panel {
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.panel--result {
  border-left: 3px solid var(--accent-dark);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.panel-subheader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.panel-title {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--text-heading);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.panel-actions {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-wrap: wrap;
}

.panel-hint {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.panel-footer {
  margin-top: 0.5rem;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ── Buttons ─────────────────────────────────────────────────── */
.btn {
  cursor: pointer;
  border: none;
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.85rem;
  font-weight: 500;
  padding: 0.45rem 0.9rem;
  transition: opacity 0.1s, background 0.1s;
  white-space: nowrap;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn--primary {
  background: var(--accent-dark);
  color: #fff;
}
.btn--primary:not(:disabled):hover { background: var(--accent); }

.btn--secondary {
  background: var(--bg-surface);
  color: var(--text);
  border: 1px solid var(--border);
}
.btn--secondary:not(:disabled):hover { border-color: var(--accent); color: var(--accent); }

.btn--ghost {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid transparent;
}
.btn--ghost:not(:disabled):hover { color: var(--text); border-color: var(--border); }

.btn--accent {
  background: var(--green-bg);
  color: var(--green);
  border: 1px solid var(--green);
}
.btn--accent:not(:disabled):hover { background: #185c2e; }

.btn--sm {
  font-size: 0.78rem;
  padding: 0.3rem 0.65rem;
}

/* ── Textareas / Code editor ─────────────────────────────────── */
.code-textarea {
  width: 100%;
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 0.8rem;
  line-height: 1.55;
  padding: 0.75rem;
  resize: vertical;
  outline: none;
  tab-size: 4;
}

.code-textarea:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 2px rgba(88,166,255,.15);
}

.code-textarea--error {
  border-color: #3b1a1a;
}

.code-textarea--error:focus {
  border-color: var(--red);
  box-shadow: 0 0 0 2px rgba(248,81,73,.15);
}

.analyze-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

/* ── Workflow Status ─────────────────────────────────────────── */
.workflow-status {
  display: flex;
  align-items: center;
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 0.85rem 1.25rem;
  overflow-x: auto;
}

.workflow-step {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  flex-shrink: 0;
}

.workflow-node {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72rem;
  font-weight: 600;
  border: 2px solid var(--border);
  color: var(--text-muted);
  background: var(--bg-surface);
  flex-shrink: 0;
}

.workflow-label {
  font-size: 0.78rem;
  color: var(--text-muted);
  white-space: nowrap;
}

.workflow-connector {
  width: 32px;
  height: 2px;
  margin: 0 0.35rem;
  border-radius: 1px;
  flex-shrink: 0;
}

.workflow-connector--done    { background: var(--green); }
.workflow-connector--pending { background: var(--border); }

.workflow-step--active .workflow-node {
  border-color: var(--accent);
  background: rgba(31,111,235,0.15);
  color: var(--accent);
}
.workflow-step--active .workflow-label {
  color: var(--accent);
  font-weight: 600;
}

.workflow-step--done .workflow-node {
  border-color: var(--green);
  background: var(--green-bg);
  color: var(--green);
}
.workflow-step--done .workflow-label {
  color: var(--green);
}

/* ── Analysis Panel ──────────────────────────────────────────── */
.analysis-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
}

@media (max-width: 600px) {
  .analysis-grid { grid-template-columns: 1fr; }
}

.analysis-field {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.55rem 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.analysis-field--wide {
  grid-column: 1 / -1;
}

.field--highlight {
  border-color: var(--accent-dark);
  background: rgba(31,111,235,0.08);
}

.field-label {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--text-muted);
}

.field-value {
  font-size: 0.85rem;
  color: var(--text-heading);
  word-break: break-word;
}

.field-value--mono {
  font-family: var(--font-mono);
  color: var(--accent);
}

.confidence-badge {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.65rem;
  border-radius: 999px;
}

.confidence--high   { background: var(--green-bg);  color: var(--green);  }
.confidence--medium { background: var(--yellow-bg); color: var(--yellow); }
.confidence--low    { background: var(--red-bg);    color: var(--red);    }

/* ── Fix Panel ───────────────────────────────────────────────── */
.fix-explanation,
.fix-proposed-change {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.65rem 0.85rem;
}

.subsection-title {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--text-muted);
  margin-bottom: 0.3rem;
}

.explanation-text {
  font-size: 0.85rem;
  color: var(--text);
  line-height: 1.6;
}

/* Code tabs */
.code-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
}

.code-tab {
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 0.8rem;
  padding: 0.45rem 0.85rem;
  font-family: var(--font-sans);
}

.code-tab:hover { color: var(--text); }

.code-tab--active {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-weight: 600;
}

/* Code blocks */
.code-block {
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.75rem;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  line-height: 1.55;
  overflow-x: auto;
  white-space: pre;
