  --bg-surface:  #1c2128;
  --bg-code:     #0d1117;
  --border:      #30363d;
  --border-focus:#58a6ff;
  --text:        #c9d1d9;
  --text-muted:  #6e7681;
  --text-heading:#e6edf3;
  --accent:      #58a6ff;
  --accent-dark: #1f6feb;
  --green:       #3fb950;
  --green-bg:    #0d4429;
  --red:         #f85149;
  --red-bg:      #3b0a0a;
  --yellow:      #d29922;
  --yellow-bg:   #3d2d00;
  --diff-add-bg: #0d4429;
  --diff-del-bg: #3b0a0a;
  --diff-hunk:   #1f6feb;

  --font-sans:   -apple-system, "Segoe UI", system-ui, sans-serif;
  --font-mono:   "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

  --radius:      6px;
  --radius-lg:   10px;
  --shadow:      0 1px 3px rgba(0,0,0,.4);
}

/* ── Reset / Base ───────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 15px;
  -webkit-text-size-adjust: 100%;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  line-height: 1.6;
  min-height: 100vh;
}

/* Visually hidden helper for screen-reader labels */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

