  flex-shrink: 0;
}

.backend-status--online  .status-dot { background: var(--green); }
.backend-status--offline .status-dot { background: var(--red); }
.backend-status--checking .status-dot { background: var(--yellow); }
.backend-status--online  { color: var(--green); border-color: var(--green-bg); }
.backend-status--offline { color: var(--red);   border-color: var(--red-bg); }

