  background: var(--yellow-bg);
  border: 1px solid var(--yellow);
  border-radius: var(--radius);
  color: var(--yellow);
  font-size: 0.82rem;
  padding: 0.6rem 0.85rem;
}

/* ── Footer ─────────────────────────────────────────────────── */
.app-footer {
  text-align: center;
  font-size: 0.72rem;
  color: var(--text-muted);
  padding: 1.5rem 1rem;
  border-top: 1px solid var(--border);
}

