+  display: flex;
+  align-items: center;
+  gap: 0.45rem;
+  flex-shrink: 0;
+}
+
+.workflow-node {
+  width: 26px;
+  height: 26px;
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 0.72rem;
+  font-weight: 600;
+  border: 2px solid var(--border);
+  color: var(--text-muted);
+  background: var(--bg-surface);
+  flex-shrink: 0;
+}
+
+.workflow-label {
+  font-size: 0.78rem;
+  color: var(--text-muted);
+  white-space: nowrap;
+}
+
+.workflow-connector {
+  width: 32px;
+  height: 2px;
+  margin: 0 0.35rem;
+  border-radius: 1px;
+  flex-shrink: 0;
+}
+
+.workflow-connector--done    { background: var(--green); }
+.workflow-connector--pending { background: var(--border); }
+
+.workflow-step--active .workflow-node {
+  border-color: var(--accent);
+  background: rgba(31,111,235,0.15);
+  color: var(--accent);
+}
+.workflow-step--active .workflow-label {
+  color: var(--accent);
+  font-weight: 600;
+}
+
+.workflow-step--done .workflow-node {
+  border-color: var(--green);
+  background: var(--green-bg);
+  color: var(--green);
+}
+.workflow-step--done .workflow-label {
+  color: var(--green);
+}
+
+/* ── Analysis Panel ──────────────────────────────────────────── */
+.analysis-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 0.65rem;
+}
+
+@media (max-width: 600px) {
+  .analysis-grid { grid-template-columns: 1fr; }
+}
+
+.analysis-field {
+  background: var(--bg-surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 0.55rem 0.75rem;
+  display: flex;
+  flex-direction: column;
+  gap: 0.15rem;
+}
+
+.analysis-field--wide {
+  grid-column: 1 / -1;
+}
+
+.field--highlight {
+  border-color: var(--accent-dark);
+  background: rgba(31,111,235,0.08);
+}
+
+.field-label {
+  font-size: 0.68rem;
+  text-transform: uppercase;
+  letter-spacing: 0.07em;
+  color: var(--text-muted);
+}
+
+.field-value {
+  font-size: 0.85rem;
+  color: var(--text-heading);
+  word-break: break-word;
+}
+
+.field-value--mono {
+  font-family: var(--font-mono);
+  color: var(--accent);
+}
+
+.confidence-badge {
+  font-size: 0.75rem;
+  font-weight: 600;
+  padding: 0.25rem 0.65rem;
+  border-radius: 999px;
+}
+
+.confidence--high   { background: var(--green-bg);  color: var(--green);  }
+.confidence--medium { background: var(--yellow-bg); color: var(--yellow); }
+.confidence--low    { background: var(--red-bg);    color: var(--red);    }
+
+/* ── Fix Panel ───────────────────────────────────────────────── */
+.fix-explanation,
+.fix-proposed-change {
+  background: var(--bg-surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 0.65rem 0.85rem;
+}
+
+.subsection-title {
+  font-size: 0.72rem;
+  text-transform: uppercase;
+  letter-spacing: 0.07em;
+  color: var(--text-muted);
+  margin-bottom: 0.3rem;
+}
+
+.explanation-text {
+  font-size: 0.85rem;
+  color: var(--text);
+  line-height: 1.6;
+}
+
+/* Code tabs */
+.code-tabs {
+  display: flex;
+  gap: 0;
+  border-bottom: 1px solid var(--border);
+}
+
+.code-tab {
+  background: transparent;
+  border: none;
+  border-bottom: 2px solid transparent;
+  color: var(--text-muted);
+  cursor: pointer;
+  font-size: 0.8rem;
+  padding: 0.45rem 0.85rem;
+  font-family: var(--font-sans);
+}
+
+.code-tab:hover { color: var(--text); }
+
+.code-tab--active {
+  color: var(--accent);
+  border-bottom-color: var(--accent);
+  font-weight: 600;
+}
+
+/* Code blocks */
+.code-block {
+  background: var(--bg-code);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 0.75rem;
+  font-family: var(--font-mono);
+  font-size: 0.78rem;
+  line-height: 1.55;
+  overflow-x: auto;
+  white-space: pre;
+  color: var(--text);
+}
+
+.code-block--compact { font-size: 0.75rem; }
+.code-block--fixed { border-color: var(--green); }
+.code-block--stderr { color: var(--red); }
+
+/* Diff colouring */
+.diff-add    { display: block; background: var(--diff-add-bg); color: var(--green); }
+.diff-remove { display: block; background: var(--diff-del-bg); color: var(--red); }
+.diff-hunk   { display: block; color: var(--diff-hunk); }
+
+.applied-notice {
+  display: flex;
+  align-items: center;
+  flex-wrap: wrap;
+}
+
+/* ── Test Results ────────────────────────────────────────────── */
+.test-results {
+  border-top: 1px solid var(--border);
+  padding-top: 0.75rem;
+  display: flex;
+  flex-direction: column;
+  gap: 0.65rem;
+}
+
+.test-summary-row {
+  display: flex;
+  align-items: center;
+  gap: 0.75rem;
+  flex-wrap: wrap;
+}
+
+.test-status-badge {
+  font-size: 0.82rem;
+  font-weight: 700;
+  padding: 0.3rem 0.75rem;
+  border-radius: var(--radius);
+}
+
+.test-status-badge--pass { background: var(--green-bg); color: var(--green); }
+.test-status-badge--fail { background: var(--red-bg);   color: var(--red);   }
+
+.test-counts {
+  font-size: 0.8rem;
+  color: var(--text-muted);
+}
+
+.tests-passed { color: var(--green); }
+.tests-failed { color: var(--red); }
+.tests-errors { color: var(--yellow); }
+
+.return-code {
+  font-size: 0.75rem;
+  color: var(--text-muted);
+  font-family: var(--font-mono);
+  margin-left: auto;
+}
+
+.test-summary-text { }
+
+.test-output {
+  display: flex;
+  flex-direction: column;
+  gap: 0.5rem;
+}
+
+.output-label {
+  font-size: 0.72rem;
+  text-transform: uppercase;
+  letter-spacing: 0.07em;
+  color: var(--text-muted);
+  margin-bottom: 0.2rem;
+}
+
+/* ── Badges ─────────────────────────────────────────────────── */
+.badge {
+  font-size: 0.72rem;
+  font-weight: 600;
+  padding: 0.2rem 0.55rem;
+  border-radius: 999px;
+}
+
+.badge--green  { background: var(--green-bg);  color: var(--green);  }
+.badge--yellow { background: var(--yellow-bg); color: var(--yellow); }
+
+/* ── Banners ─────────────────────────────────────────────────── */
+.error-banner {
+  background: var(--red-bg);
+  border: 1px solid var(--red);
+  border-radius: var(--radius);
+  color: var(--red);
+  font-size: 0.85rem;
+  padding: 0.65rem 0.85rem;
+  display: flex;
+  align-items: center;
+  gap: 0.5rem;
+}
+
+.error-banner strong { flex-shrink: 0; }
+
+.error-banner-close {
+  margin-left: auto;
+  background: none;
+  border: none;
+  color: var(--red);
+  cursor: pointer;
+  font-size: 0.9rem;
+  padding: 0.1rem 0.3rem;
+  border-radius: 3px;
+  flex-shrink: 0;
+}
+.error-banner-close:hover { background: rgba(248,81,73,.2); }
+
+.warn-banner {
+  background: var(--yellow-bg);
+  border: 1px solid var(--yellow);
+  border-radius: var(--radius);
+  color: var(--yellow);
+  font-size: 0.82rem;
+  padding: 0.6rem 0.85rem;
+}
+
+.warn-banner code {
+  background: rgba(0,0,0,.2);
+  padding: 0.1rem 0.35rem;
+  border-radius: 3px;
+  font-family: var(--font-mono);
+  font-size: 0.8em;
+}
+
+/* ── Info box ────────────────────────────────────────────────── */
+.info-box--warning {
+  background: var(--yellow-bg);
+  border: 1px solid var(--yellow);
+  border-radius: var(--radius);
+  color: var(--yellow);
+  font-size: 0.82rem;
+  padding: 0.6rem 0.85rem;
+}
+
+/* ── Footer ─────────────────────────────────────────────────── */
+.app-footer {
+  text-align: center;
+  font-size: 0.72rem;
+  color: var(--text-muted);
+  padding: 1.5rem 1rem;
+  border-top: 1px solid var(--border);
+}
